const lv_image_dsc_t *standby_glyph_image(char glyph)
{
    if (glyph >= '0' && glyph <= '9')
    {
        static const lv_image_dsc_t *digits[10] = {
            &standby_glyph_digit_0,
            &standby_glyph_digit_1,
            &standby_glyph_digit_2,
            &standby_glyph_digit_3,
            &standby_glyph_digit_4,
            &standby_glyph_digit_5,
            &standby_glyph_digit_6,
            &standby_glyph_digit_7,
            &standby_glyph_digit_8,
            &standby_glyph_digit_9,
        };

        return digits[glyph - '0'];
    }
    if (glyph == ':')
    {
        return &standby_glyph_colon;
    }

    return NULL;
}
